#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
constexpr int GUARD=16384;
std::vector<double>load(const char*name,size_t n){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=(std::streamoff)(n*8))exit(3);f.seekg(0);std::vector<double>a(n);f.read((char*)a.data(),n*8);if(!f)exit(3);return a;}
template<class T>struct Buffer{size_t n;T*base,*data;std::vector<T>initial,host;Buffer(int N,T value):n(N),initial(n+16,GUARD),host(n+16){std::fill(initial.begin()+8,initial.begin()+8+n,value);CK(cudaMalloc(&base,(n+16)*sizeof(T)));data=base+8;copyin();}Buffer(int N,const std::vector<double>&pre,size_t&pos):Buffer(N,T(0)){for(size_t i=0;i<n;++i)initial[8+i]=pre[pos++];copyin();}void copyin(){CK(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}void read(){CK(cudaMemcpy(host.data(),base,host.size()*sizeof(T),cudaMemcpyDeviceToHost));}};
struct Outcome{std::vector<double>values;double seconds,extract_seconds,compress_seconds;bool ok;};
struct Case{int nr,nc,steps,N,blocks;float lambda;Buffer<float>I,s,s2,dN,dS,dE,dW,c;Buffer<int>iN,iS,jE,jW;std::vector<float>stats;
Case(int r,int co,int it,float l,const std::vector<double>&pre,size_t&pos):nr(r),nc(co),steps(it),N(r*co),blocks((N+255)/256),lambda(l),I(N,pre,pos),s(N,0.f),s2(N,0.f),dN(N,0.f),dS(N,0.f),dE(N,0.f),dW(N,0.f),c(N,0.f),iN(nr,pre,pos),iS(nr,pre,pos),jE(nc,pre,pos),jW(nc,pre,pos),stats(5*steps){}
Outcome execute(){Outcome z;z.ok=true;for(auto b:{&I,&s,&s2,&dN,&dS,&dE,&dW,&c})b->copyin();std::fill(stats.begin(),stats.end(),0);I.read();auto raw=I.host;z.ok&=raw==I.initial;CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();extract<<<blocks,256>>>((long)N,I.data);CK(cudaDeviceSynchronize());z.extract_seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();I.read();auto extracted=I.host;
start=std::chrono::steady_clock::now();for(int it=0;it<steps;++it){prepare<<<blocks,256>>>((long)N,I.data,s.data,s2.data);int no=N,mul=1,b=blocks;while(b){reduce<<<b,256>>>((long)N,no,mul,s.data,s2.data);no=b;if(b==1)b=0;else{mul*=256;b=(b+255)/256;}}float total,total2;CK(cudaMemcpy(&total,s.data,4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(&total2,s2.data,4,cudaMemcpyDeviceToHost));float mean=total/float(N),mean2=mean*mean,var=total2/float(N)-mean2,q0=var/mean2;stats[5*it]=total;stats[5*it+1]=total2;stats[5*it+2]=mean;stats[5*it+3]=var;stats[5*it+4]=q0;
srad<<<blocks,256>>>(lambda,nr,nc,(long)N,iN.data,iS.data,jE.data,jW.data,dN.data,dS.data,dE.data,dW.data,q0,c.data,I.data);srad2<<<blocks,256>>>(lambda,nr,nc,(long)N,iN.data,iS.data,jE.data,jW.data,dN.data,dS.data,dE.data,dW.data,c.data,I.data);}
CK(cudaDeviceSynchronize());z.seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();I.read();auto precompress=I.host;start=std::chrono::steady_clock::now();compress<<<blocks,256>>>((long)N,I.data);CK(cudaDeviceSynchronize());z.compress_seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();for(auto b:{&I,&s,&s2,&dN,&dS,&dE,&dW,&c})b->read();for(auto b:{&iN,&iS,&jE,&jW})b->read();auto payload=[&](auto&v){for(size_t i=8;i<v.size()-8;++i)z.values.push_back(v[i]);};payload(I.host);payload(precompress);for(auto b:{&s,&s2,&dN,&dS,&dE,&dW,&c})payload(b->host);payload(raw);payload(extracted);for(auto b:{&iN,&iS,&jE,&jW}){z.ok&=b->host==b->initial;payload(b->host);}for(float v:stats)z.values.push_back(v);auto guard=[&](auto&b){for(size_t i=0;i<b.host.size();++i)if(i<8||i>=b.n+8){z.values.push_back(b.host[i]);z.ok&=b.host[i]==GUARD;}};for(auto b:{&I,&s,&s2,&dN,&dS,&dE,&dW,&c})guard(*b);for(auto b:{&iN,&iS,&jE,&jW})guard(*b);
double initialmass=0,finalmass=0,minI=1e9,maxI=-1e9;for(int i=0;i<N;++i){initialmass+=extracted[8+i];finalmass+=precompress[8+i];minI=std::min(minI,double(extracted[8+i]));maxI=std::max(maxI,double(extracted[8+i]));z.ok&=std::isfinite(c.host[8+i])&&c.host[8+i]>=0&&c.host[8+i]<=1;}for(int i=0;i<N;++i)z.ok&=precompress[8+i]>=minI-1e-5&&precompress[8+i]<=maxI+1e-5;z.ok&=fabs(initialmass-finalmass)<=3e-6*fabs(initialmass);for(int i=0;i<steps;++i)z.ok&=stats[5*i+3]>0&&stats[5*i+4]>0;return z;}
};
int main(){auto pre=load(FIXTURE,69310),gold=load(ORACLE,746001);size_t pos=1;std::vector<Case*>cases;for(int ci=0;ci<4;++ci){int nr=pre[pos++],nc=pre[pos++],it=pre[pos++];float l=pre[pos++];cases.push_back(new Case(nr,nc,it,l,pre,pos));}if(pos!=pre.size())return 3;for(auto c:cases){auto z=c->execute();if(!z.ok)return 4;}
for(int trial=1;trial<=5;++trial){auto art=pre;std::vector<double>times,ext,comp;bool ok=true;double ma=0;for(auto c:cases){auto z=c->execute();ok&=z.ok;art.insert(art.end(),z.values.begin(),z.values.end());times.push_back(z.seconds);ext.push_back(z.extract_seconds);comp.push_back(z.compress_seconds);}if(art.size()!=pre.size()+gold.size())return 3;for(size_t i=0;i<gold.size();++i){double actual=art[pre.size()+i],e=fabs(actual-gold[i]);ok&=std::isfinite(actual)&&e<=1e-4+1e-5*fabs(gold[i]);ma=std::max(ma,e);}std::string name="output_trial"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write((char*)art.data(),art.size()*8);if(!f)return 3;double total=0;for(double t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"timing_region\":\"sum4_SRAD_compute_prepare_reduce_D2Hstats_diffusion_iterations\",\"jit_excluded\":true,\"internal_repeats\":1,\"native_reference_repaired\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}",trial,total,ok?"true":"false",art.size(),ma,name.c_str(),art.size());auto emit=[&](const char*name,std::vector<double>&a){printf(",\"%s\":[",name);for(size_t i=0;i<a.size();++i)printf("%s%.17g",i?",":"",a[i]);printf("]");};emit("path_times_seconds",times);emit("extract_times_seconds_outside_primary_ROI",ext);emit("compress_times_seconds_outside_primary_ROI",comp);printf(",\"compute_launches\":51,\"statistics_telemetry_F32_stores_inside_ROI\":50}\n");}
